ar het verleden te kijken. De films die daar worden aangeboden passen niet bij een gewone voorstelling. Haar nieuwsgierigheid brengt haar op een zoektocht die ook raakt aan de afstand tussen haar en haar vader.","source_type":"official_catalog","source_name":"Bibliografische bron; oorspronkelijke gecontroleerde samenvatting","source_url":"https://metadata.isbn.nl/1429512/films-die-nergens-draaien.html","provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-01T21:37:32Z","review_batch":"nl007-reviewed-batch-07-20261101","evidence":[{"url":"https://metadata.isbn.nl/1429512/films-die-nergens-draaien.html","sha256":"b1d3cd0d79a43d6604b47824881e2b6493d639de58ff972f279d60ed2c8baf91","checkedAt":"2026-11-01T20:43:05.519Z","fact":"Hardback ISBN 9789021681825 Nieuwe editie verschijningsdatum 15/09/2021 NUR 283 Fictie 10-12 jaar 284 Fictie 13-15 jaar imprint Ploegsma uitgever WPG Kindermedia taal Nederlands","sourceAuthors":"Yorick Goldewijk"},{"url":"https://metadata.isbn.nl/1429512/films-die-nergens-draaien.html","checkedAt":"2026-11-01T21:37:32Z","fact":"Work-bound content reviewed; original factual Dutch summary, not source quotation or title-derived content."}]}},{"relation":"catalog_edition_metadata","ref":"metadata:9789045131153","key":{"edition_id":945201652},"before":{"format":"unknown","work_id":945101541,"evidence":[{"url":"https://openlibrary.org/books/OL62083313M","facts":["Eliza gelooft ouders niet over vijf verdronken broers, gaat met Krekel richting Witte Kliffen","Exact Dutch ISBN9789045131153 parentOL45586821W; source physical_format Hardbook remains unknown, not guessed hardcover"],"snapshot":"2026-09-30","checkedAt":"2026-10-31"}],"cover_url":null,"edition_id":945201652,"bound_title":"Krekel","reviewed_at":"2026-10-31T00:00:00+00:00","bound_isbn13":"9789045131153","evidence_url":"https://openlibrary.org/books/OL62083313M","review_batch":"integrity-edition-source-ten-20261031","review_status":"approved","bound_lang